const event = $('From Dispatcher').first().json;
const ai = JSON.parse($json.choices[0].message.content);
const evidence = ai.extracted_evidence || {};
if (evidence.customer_fit && evidence.customer_fit.excluded_signal == null) evidence.customer_fit.excluded_signal = false;
const confidence = Number(ai.extraction_confidence ?? ai.confidence ?? 0);
const payload = { extracted_evidence: evidence, confidence, missing_information: ai.missing_information || [], recommended_next_action: ai.recommended_next_action || null, ai_provider: $env.AI_PROVIDER || 'aliyun_bailian', ai_model: $json.model, input_tokens: $json.usage?.prompt_tokens || 0, output_tokens: $json.usage?.completion_tokens || 0, latency_ms: $json.latency_ms || null, prompt_version: 'standard_v1-evidence-2', reason: 'lead_intake' };
return [{ json: { command_id: event.id, idempotency_key: 'score:' + event.id, command_name: 'record_lead_score', organization_id: event.organization_id, actor_user_id: $env.SYSTEM_ACTOR_USER_ID, target_type: 'lead', target_id: event.aggregate_id, expected_version: null, source: 'n8n', occurred_at: new Date().toISOString(), payload } }];
